class Solution {
public:
    bool isHappy(int n) {
        set<int> seen;
        while (n != 1 && !seen.count(n)) {
            seen.insert(n);
            int next = 0;
            while (n > 0) {
                next += (n % 10) * (n % 10);
                n /= 10;
            }
            n = next;
        }
        return n == 1;
    }
};
